
const DATA_B64 = "";

/* ===================== НАСТРОЙКИ ===================== */
const QUESTION_COUNT = 10;   /* основни въпроси; бонус въпросът (шах) се добавя накрая като +1 */
const RECENT_WINDOW  = 3;    /* колко от последните тестове да се избягват при подбора на въпроси */
const HISTORY_KEY    = "gaming-trivia-history-v1";

function decodeQuestionData(b64){
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
  return JSON.parse(new TextDecoder("utf-8").decode(bytes));
}

/* нивата на трудност, както са записани в questions.json (1 = най-лесно) */
const DIFF_LEVELS = {"нормално":1, "средно труден":2, "едно ниво над средно":3, "доста трудни":4, "много трудно":5};
function diffLevel(label){ return DIFF_LEVELS[String(label||"").trim().toLowerCase()] || 3; }
function hashStr(s){ let h = 5381; for(let i=0;i<s.length;i++) h = ((h<<5)+h+s.charCodeAt(i))|0; return (h>>>0).toString(36); }

/* плосък списък: {key, cat, series, q, options, correct, diff, lvl, spoiler, bonus} */
const ALL = decodeQuestionData(DATA_B64).map(r=>{
  const c = r.answers.indexOf(r.correctAnswer);
  return {key:hashStr(r.question), sid:r.category+"|"+(r.series || "Общи въпроси"), cat:r.category, series:r.series || "Общи въпроси", q:r.question,
          options:r.answers, correct:(c === -1 ? 0 : c), diff:r.difficulty, lvl:diffLevel(r.difficulty),
          spoiler:!!r.spoiler, bonus:!!r.bonus};
});

/* инди студиата; всички останали се броят за популярни заглавия */
const INDIE_STUDIOS = ["Croteam","Killmonday Games","Night School","Rusty Lake","Frictional Games","Amanita Design","Edmund McMillen"];
ALL.forEach(q=>{ q.tier = INDIE_STUDIOS.indexOf(q.cat) !== -1 ? "indie" : "popular"; });
const QUICK_TIERS = [
  {id:"popular", icon:"\u2605", name:"ПОПУЛЯРНИ ЗАГЛАВИЯ", desc:"Големите имена — Rockstar, Capcom, Konami, Valve, Xbox..."},
  {id:"indie",   icon:"\u25C6", name:"ИНДИ", desc:"Независими студия — Croteam, Rusty Lake, Amanita, Frictional..."},
  {id:"mixed",   icon:"\u25CF", name:"ОБЩО / СМЕСЕНО", desc:"Микс от популярни и инди заглавия."}
];

const CATEGORIES = (()=>{
  const m = {};
  ALL.filter(q=>!q.bonus).forEach(q=>{
    const c = m[q.cat] = m[q.cat] || {name:q.cat, count:0, series:{}};
    c.count++;
    const s = c.series[q.sid] = c.series[q.sid] || {id:q.sid, name:q.series, count:0};
    s.count++;
  });
  return Object.keys(m).map(k=>({name:m[k].name, count:m[k].count, series:Object.keys(m[k].series).map(s=>m[k].series[s])}))
    .sort((a,b)=>b.count-a.count || a.name.localeCompare(b.name));
})();

const $ = id => document.getElementById(id);
function esc(s){ return String(s===undefined||s===null ? "" : s).replace(/[&<>]/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;"}[c])); }
function shuffle(arr){
  for(let i=arr.length-1;i>0;i--){ const j = Math.floor(Math.random()*(i+1)); [arr[i],arr[j]] = [arr[j],arr[i]]; }
  return arr;
}

/* ===================== ИСТОРИЯ (кои въпроси са излизали наскоро) =====================
   Пази се в браузъра (localStorage) на този компютър: за всеки въпрос  в кой по ред тест е излизал последно.
   Така следващият човек получава други въпроси, а най-отдавна неизлизалите излизат първи. */
function loadUsage(){
  try{
    const h = JSON.parse(localStorage.getItem(HISTORY_KEY));
    if(h && typeof h.session === "number" && h.used) return h;
  }catch(e){}
  return {session:0, used:{}};
}
function saveUsage(){ try{ localStorage.setItem(HISTORY_KEY, JSON.stringify(usageLog)); }catch(e){} }
const usageLog = loadUsage();

/* ===================== ПОДБОР НА ВЪПРОСИ ===================== */
/* по-малкият ранг печели: [излизал наскоро?, въпроси от същото студио в този тест, от същата поредица,
   кога е излизал последно (никога = най-напред), случайност] */
function rankOf(q, picked, sNo){
  const u = usageLog.used[q.key];
  const recent = (u !== undefined && sNo - u <= RECENT_WINDOW) ? 1 : 0;
  const studioN = picked.filter(p=>p.cat === q.cat).length;
  const seriesN = picked.filter(p=>p.cat === q.cat && p.series === q.series).length;
  return [recent, studioN, seriesN, u === undefined ? -1 : u, Math.random()];
}
function pickBest(cands, picked, sNo){
  let best = null, bestR = null;
  cands.forEach(q=>{
    const r = rankOf(q, picked, sNo);
    let better = !best;
    for(let i=0; !better && i<r.length; i++){ if(r[i] !== bestR[i]){ better = r[i] < bestR[i]; break; } }
    if(better){ best = q; bestR = r; }
  });
  return best;
}
/* всеки път разбърква отговорите, за да не помага запомнянето на позицията */
function prepare(q){
  const opts = shuffle(q.options.map((o,i)=>({o,i})));
  return Object.assign({}, q, {options:opts.map(x=>x.o), correct:opts.findIndex(x=>x.i === q.correct)});
}

function buildTest(tier, sel){
  usageLog.session++;
  const sNo = usageLog.session;
  const regular = ALL.filter(q=>!q.bonus && (tier ? (tier === "mixed" || q.tier === tier) : sel.has(q.sid))), bonusPool = ALL.filter(q=>q.bonus);
  const levels = Array.from(new Set(regular.map(q=>q.lvl))).sort((a,b)=>a-b);
  const target = Math.min(QUESTION_COUNT, regular.length);

  /* поравно по нива на трудност; остатъкът отива на случайни нива; редът е случаен */
  const slots = [];
  if(levels.length){
    const base = Math.floor(target/levels.length), extra = target - base*levels.length;
    shuffle(levels.slice()).forEach((l,i)=>{ for(let k=0;k<base+(i<extra?1:0);k++) slots.push(l); });
    shuffle(slots);
  }
  /* смесен режим: около 60% популярни и 40% инди */
  let srcs = null;
  if(tier === "mixed"){
    const n = slots.length, indieN = n > 1 ? Math.min(n-1, Math.max(1, Math.round(n*0.4))) : 0;
    srcs = shuffle(slots.map((_,i)=>i < indieN ? "indie" : "popular"));
  }
  const picked = [];
  slots.forEach((l,si)=>{
    const left = regular.filter(q=>picked.indexOf(q) === -1);
    let cands = left.filter(q=>q.lvl === l && (!srcs || q.tier === srcs[si]));
    if(!cands.length) cands = left.filter(q=>q.lvl === l);
    if(!cands.length && left.length){
      const m = Math.min.apply(null, left.map(q=>Math.abs(q.lvl-l)));
      cands = left.filter(q=>Math.abs(q.lvl-l) === m);
    }
    if(cands.length) picked.push(pickBest(cands, picked, sNo));
  });

  const test = picked.map(prepare);
  if(bonusPool.length) test.push(prepare(pickBest(bonusPool, [], sNo))); 
  test.forEach(q=>{ usageLog.used[q.key] = sNo; });
  saveUsage();
  return test;
}


const state = {questions:[], idx:0, answers:[], ack:new Set(), rows:[]};
const setup = {mode:"quick", tier:"mixed", sel:new Set()}; 

function showScreen(id){
  document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active"));
  $(id).classList.add("active");
  $("backBtn").style.display = (id === "screen-start") ? "none" : "block";
  window.scrollTo(0,0);
}
function resetAll(){
  state.questions = []; state.answers = []; state.rows = []; state.ack = new Set(); state.idx = 0;
  $("startErr").textContent = "";
  showScreen("screen-start");
}
$("backBtn").onclick = ()=>{
  if($("screen-quiz").classList.contains("active") && !confirm("Да прекратя ли теста? Отговорите ще се загубят.")) return;
  resetAll();
};

function startTest(){
  if(!ALL.length){ $("startErr").textContent = "НЯМА ЗАРЕДЕНИ ВЪПРОСИ."; return; }
  const hasPool = setup.mode === "quick" || setup.sel.size > 0;
  if(!hasPool){ $("startErr").textContent = "ИЗБЕРИ ПОНЕЧЕ ЕДНА КАТЕГОРИЯ."; return; }
  $("startErr").textContent = "";
  state.questions = buildTest(setup.mode === "quick" ? setup.tier : null, setup.sel);
  state.idx = 0; state.ack = new Set();
  state.answers = new Array(state.questions.length).fill(null);
  showScreen("screen-quiz");
  renderQuestion();
}


function swapPool(idx){
  const cur = state.questions[idx], inTest = new Set(state.questions.map(q=>q.key));
  return ALL.filter(q=>!inTest.has(q.key) && q.bonus === cur.bonus && !q.spoiler &&
    (cur.bonus || (setup.mode === "quick" ? (setup.tier === "mixed" || q.tier === setup.tier) : setup.sel.has(q.sid))));
}

function renderQuestion(){
  const total = state.questions.length, q = state.questions[state.idx];
  $("qIdx").textContent = state.idx+1;
  $("qTotal").textContent = total;
  $("qCat").textContent = q.bonus ? q.cat : (q.cat + " · " + q.series);
  $("bonusTag").style.display = q.bonus ? "inline-block" : "none";
  $("progFill").style.width = Math.round(((state.idx+1)/total)*100) + "%";
  $("prevBtn").style.display = state.idx === 0 ? "none" : "inline-block";
  $("nextBtn").textContent = (state.idx === total-1) ? "[ ЗАВЪРШИ ТЕСТА ]" : "[ СЛЕДВАЩ > ]";

  const gate = q.spoiler && !state.ack.has(state.idx);
  $("spoilerBox").style.display = gate ? "flex" : "none";
  $("qText").style.display = gate ? "none" : "";
  $("qOpts").style.display = gate ? "none" : "";
  if(gate){
    $("spoilerText").textContent = "Този въпрос може да съдържа спойлер за " + q.series + " (" + q.cat + "). Искаш ли да го видиш, или да го смениш с друг?";
    $("spoilerSkipBtn").disabled = swapPool(state.idx).length === 0;
    return;
  }
  $("qText").textContent = q.q;
  const box = $("qOpts");
  box.innerHTML = "";
  q.options.forEach((opt,i)=>{
    const b = document.createElement("button");
    b.className = "opt-btn" + (state.answers[state.idx] === i ? " chosen" : "");
    b.textContent = String.fromCharCode(65+i) + ") " + opt;
    b.onclick = ()=>selectOption(i);
    box.appendChild(b);
  });
}


function selectOption(i){
  state.answers[state.idx] = i;
  Array.prototype.forEach.call($("qOpts").children, (b,j)=>b.classList.toggle("chosen", j === i));
}

function acknowledgeSpoiler(){ state.ack.add(state.idx); renderQuestion(); }
function swapQuestion(){
  const idx = state.idx, cur = state.questions[idx], pool = swapPool(idx);
  if(!pool.length){ acknowledgeSpoiler(); return; }
  const sameLvl = pool.filter(q=>q.lvl === cur.lvl);
  const others = state.questions.filter((_,i)=>i !== idx);
  const rep = prepare(pickBest(sameLvl.length ? sameLvl : pool, others, usageLog.session));
  state.questions[idx] = rep; state.answers[idx] = null; state.ack.delete(idx);
  usageLog.used[rep.key] = usageLog.session; saveUsage();
  renderQuestion();
}

function navQuestion(dir){
  const total = state.questions.length;
  if(dir === 1 && state.idx === total-1){ finishQuiz(); return; }
  state.idx = Math.min(Math.max(state.idx+dir, 0), total-1);
  renderQuestion();
}


document.addEventListener("keydown", e=>{
  if(!$("screen-quiz").classList.contains("active") || $("spoilerBox").style.display === "flex") return;
  const pickMap = {Digit1:0,Digit2:1,Digit3:2,Digit4:3,Numpad1:0,Numpad2:1,Numpad3:2,Numpad4:3,KeyA:0,KeyB:1,KeyC:2,KeyD:3};
  const q = state.questions[state.idx];
  if(q && e.code in pickMap){ if(pickMap[e.code] < q.options.length) selectOption(pickMap[e.code]); }
  else if(e.code === "ArrowRight") navQuestion(1);
  else if(e.code === "ArrowLeft" && state.idx > 0) navQuestion(-1);
});

/* ===================== КРАЙ И РЕЗУЛТАТ ===================== */
function buildRows(){
  return state.questions.map((q,i)=>{
    const a = state.answers[i];
    return {num:i+1, bonus:q.bonus, cat:q.cat, series:q.series, diff:q.diff || "", q:q.q, correctAns:q.options[q.correct],
            chosen:(a === null ? "—" : q.options[a]), result:(a === null ? "Без отговор" : (a === q.correct ? "Вярно" : "Грешно"))};
  });
}

function finishQuiz(){
  const missing = state.answers.map((a,i)=>a === null ? i+1 : 0).filter(Boolean);
  if(missing.length && !confirm("Неотговорени въпроси: " + missing.join(", ") + ".\nТе се броят за грешни. Да завърша ли теста?")) return;
  state.rows = buildRows();
  const reg = state.rows.filter(r=>!r.bonus), bon = state.rows.find(r=>r.bonus);
  const regOk = reg.filter(r=>r.result === "Вярно").length;
  const bonOk = !!bon && bon.result === "Вярно";

  $("summaryText").textContent = regOk + " / " + reg.length;
  let lines = "";
  if(bon) lines += '<div class="' + (bonOk ? "ok" : "bad") + '">&#9733; БОНУС ВЪПРОС: ' + (bonOk ? "ВЯРНО +1 ТОЧКА" : bon.result.toUpperCase()) + '</div>';
  lines += '<div class="total">ОБЩО: ' + (regOk + (bonOk ? 1 : 0)) + ' ТОЧКИ (МАКС. ' + state.rows.length + ')</div>';
  $("scoreLines").innerHTML = lines;
  $("exportStatsErr").textContent = "";
  renderStatsTable();
  showScreen("screen-summary");
}

/* таблицата с верните отговори*/
function renderStatsTable(){
  const answered = state.rows.filter(r=>r.result !== "Без отговор").length;
  const correct = state.rows.filter(r=>r.result === "Вярно").length;
  let html = '<div class="stats-summary-line">Отговорени: ' + answered + '/' + state.rows.length + ' · Верни: ' + correct + '</div>' +
    '<div class="stats-scroll"><table class="stats-table"><thead><tr>' +
    '<th>№</th><th>Студио · Поредица</th><th>Въпрос</th><th>Верен отговор</th><th>Отговорено</th><th>Резултат</th>' +
    '</tr></thead><tbody>';
  state.rows.forEach(r=>{
    const cls = r.result === "Вярно" ? "res-ok" : r.result === "Грешно" ? "res-bad" : "res-none";
    html += '<tr' + (r.bonus ? ' class="bonus-row"' : '') + '>' +
      '<td>' + (r.bonus ? '<span class="bonus-mark">&#9733;</span>' : r.num) + '</td>' +
      '<td>' + esc(r.bonus ? r.cat + " (бонус)" : r.cat + " · " + r.series) + '</td>' +
      '<td>' + esc(r.q) + '</td><td>' + esc(r.correctAns) + '</td><td>' + esc(r.chosen) + '</td>' +
      '<td class="' + cls + '">' + esc(r.result) + '</td></tr>';
  });
  $("statsWrap").innerHTML = html + '</tbody></table></div>';
}

/* ===================== ЕКСПОРТ (CSV) ===================== */
function csvEscape(val){
  const s = String(val === undefined || val === null ? "" : val);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g,'""') + '"' : s;
}
function exportStats(){
  const rows = [["№","Тип","Студио","Поредица","Трудност","Въпрос","Правилен отговор","Отговорено","Резултат"]];
  state.rows.forEach(r=>rows.push([r.num, r.bonus ? "Бонус" : "Основен", r.cat, r.series, r.diff, r.q, r.correctAns, r.chosen, r.result]));
  const csv = "\uFEFF" + rows.map(r=>r.map(csvEscape).join(",")).join("\r\n"); /* BOM, за да се чете кирилицата в Excel */
  const stamp = new Date().toISOString().slice(0,19).replace(/[:T]/g,"-");
  try{
    const url = URL.createObjectURL(new Blob([csv], {type:"text/csv;charset=utf-8"}));
    const a = document.createElement("a");
    a.href = url; a.download = "trivia-statistika-" + stamp + ".csv";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url), 2000);
  }catch(e){
    $("exportStatsErr").textContent = "Изтеглянето не проработи в тази среда.";
  }
}

/* ===================== ИЗБОР ПРЕДИ ТЕСТА ===================== */
function buildTierGrid(){
  const g = $("tierGrid"); g.innerHTML = "";
  QUICK_TIERS.forEach(t=>{
    const n = ALL.filter(q=>!q.bonus && (t.id === "mixed" || q.tier === t.id)).length;
    const d = document.createElement("div");
    d.className = "tier-box" + (setup.tier === t.id ? " selected" : "");
    d.innerHTML = '<div class="icon">' + t.icon + '</div><div class="name">' + esc(t.name) + '</div><div class="desc">' + esc(t.desc) + '</div><div class="count">' + n + ' ВЪПРОСА</div>';
    d.onclick = ()=>{ setup.tier = t.id; buildTierGrid(); };
    g.appendChild(d);
  });
}
function catState(c){
  const on = c.series.filter(s=>setup.sel.has(s.id)).length;
  return on === 0 ? "" : (on === c.series.length ? "selected" : "partial");
}
function buildCatGrid(){
  const g = $("catGrid"); g.innerHTML = "";
  CATEGORIES.forEach(c=>{
    const d = document.createElement("div");
    d.className = "cat-box " + catState(c);
    d.innerHTML = esc(c.name) + '<span class="count">' + c.count + ' ВЪПРОСА</span>' +
      (c.series.length > 1 ? '<span class="series-btn">ПОРЕДИЦИ</span>' : '');
    d.onclick = e=>{
      if(e.target.classList.contains("series-btn")){ openSeriesModal(c); return; }
      const all = c.series.every(s=>setup.sel.has(s.id));
      c.series.forEach(s=>{ if(all) setup.sel.delete(s.id); else setup.sel.add(s.id); });
      buildCatGrid();
    };
    g.appendChild(d);
  });
  $("selCount").textContent = ALL.filter(q=>!q.bonus && setup.sel.has(q.sid)).length;
}
let modalCat = null;
function openSeriesModal(c){
  modalCat = c;
  $("modalTitle").textContent = c.name.toUpperCase();
  const list = $("modalSeriesList"); list.innerHTML = "";
  c.series.forEach(s=>{
    const r = document.createElement("div");
    r.className = "series-row" + (setup.sel.has(s.id) ? " checked" : "");
    r.innerHTML = '<span class="box">' + (setup.sel.has(s.id) ? "&#10003;" : "") + '</span><span class="label">' + esc(s.name) + '</span><span class="qc">' + s.count + '</span>';
    r.onclick = ()=>{ if(setup.sel.has(s.id)) setup.sel.delete(s.id); else setup.sel.add(s.id); openSeriesModal(c); buildCatGrid(); };
    list.appendChild(r);
  });
  $("seriesModal").classList.add("active");
}
function closeSeriesModal(){ $("seriesModal").classList.remove("active"); modalCat = null; }
document.querySelectorAll("#modeRow .pill").forEach(p=>{
  p.onclick = ()=>{
    setup.mode = p.dataset.mode;
    document.querySelectorAll("#modeRow .pill").forEach(x=>x.classList.toggle("selected", x === p));
    $("quickPanel").classList.toggle("is-hidden", setup.mode !== "quick");
    $("detailedPanel").classList.toggle("is-hidden", setup.mode !== "detailed");
  };
});

/* ===================== СТАРТ ===================== */
buildTierGrid();
buildCatGrid();
$("infoCount").textContent = Math.min(QUESTION_COUNT, ALL.filter(q=>!q.bonus).length);